package importer

// The golden test pins what the region and place imports make of the
// Pattaya fixture, exactly as `docker compose up` runs them (cmd/regions,
// then cmd/places, country th, FixtureBBox). It was generated by the
// importer code as it stood before the country import (stage 2 and 3,
// docs/COUNTRY_IMPORT_STAGE2_BRIEF.md) changed anything, and every later
// change must leave it passing unchanged: Thailand's import must not change.
//
// Regenerate testdata/golden/pattaya-import.json only on purpose, when a
// change to Thailand's import has been decided (a line in docs/decisions.md),
// and review the diff:
//
//	TEST_DATABASE_URL=... go test ./internal/importer -run TestGolden -update
//
// A second scenario (golden_plots_test.go, pattaya-import-plots.json) runs the
// same import with plots already in the database and a second time; -update
// regenerates both files.

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/cartograph-asia/cartograph/internal/db"
	"github.com/cartograph-asia/cartograph/migrations"
)

var update = flag.Bool("update", false, "rewrite the files in testdata/golden (on purpose only)")

// goldenPath is testdata/golden/<name> in the source tree.
func goldenPath(name string) string {
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "..", "..", "testdata", "golden", name)
}

// checkGolden compares got with testdata/golden/<name>, or rewrites the file
// under -update.
func checkGolden(t *testing.T, name string, got []byte) {
	t.Helper()
	path := goldenPath(name)
	if *update {
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, got, 0o644); err != nil {
			t.Fatal(err)
		}
		t.Logf("wrote %s (%d bytes)", path, len(got))
		return
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("%v (generate it with -update, on purpose only)", err)
	}
	if !bytes.Equal(got, want) {
		out := filepath.Join(t.TempDir(), name)
		_ = os.WriteFile(out, got, 0o644)
		t.Fatalf("the import of the Pattaya fixture differs from %s; Thailand's import must not change.\n"+
			"Compare: diff %s %s", path, path, out)
	}
}

// testDB opens a fresh, migrated schema in TEST_DATABASE_URL; the test is
// skipped when the variable is not set.
func testDB(t *testing.T) *db.DB {
	t.Helper()
	url := os.Getenv("TEST_DATABASE_URL")
	if url == "" {
		t.Skip("TEST_DATABASE_URL not set")
	}
	ctx := context.Background()
	schema := fmt.Sprintf("importer_%d", time.Now().UnixNano())
	admin, err := pgxpool.New(ctx, url)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := admin.Exec(ctx, "create schema "+schema); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_, _ = admin.Exec(context.Background(), "drop schema "+schema+" cascade")
		admin.Close()
	})
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		t.Fatal(err)
	}
	cfg.ConnConfig.RuntimeParams["search_path"] = schema
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		t.Fatal(err)
	}
	d := &db.DB{Pool: pool}
	t.Cleanup(d.Close)
	if err := d.Migrate(ctx, migrations.FS); err != nil {
		t.Fatal(err)
	}
	return d
}

func TestGoldenPattayaImport(t *testing.T) {
	d := testDB(t)
	ctx := context.Background()
	osmPath, waterPath := Fixture()
	if _, err := Regions(ctx, d, RegionOptions{PBF: osmPath, Water: waterPath, BBox: FixtureBBox, Country: "th"}); err != nil {
		t.Fatal(err)
	}
	if _, err := Places(ctx, d, PlaceOptions{PBF: osmPath, BBox: FixtureBBox}); err != nil {
		t.Fatal(err)
	}
	got, err := importSnapshot(ctx, d)
	if err != nil {
		t.Fatal(err)
	}
	checkGolden(t, "pattaya-import.json", got)
}

// Snapshot of the import: deterministic (sorted, no serial ids, no
// timestamps), floats as fixed-precision strings.
type snapshot struct {
	Counts      map[string]int   `json:"counts"`
	Regions     []snapRegion     `json:"regions"`
	PlotNumbers []snapPlotNumber `json:"plot_numbers"`
	Places      []snapPlace      `json:"places"`
	Plots       []snapPlot       `json:"plots"`
}

type snapRegion struct {
	OSMID          int64   `json:"osm_id"`
	Kind           string  `json:"kind"`
	KindName       *string `json:"kind_name,omitempty"` // only once the column exists, and only when set (Thailand keeps NULL)
	AdminLevel     int     `json:"admin_level"`
	Country        string  `json:"country"`
	Slug           string  `json:"slug"`
	NameEn         string  `json:"name_en"`
	NameLocal      *string `json:"name_local"`
	ParentOSMID    *int64  `json:"parent_osm_id"`
	Urban          bool    `json:"urban"`
	LandCells      int     `json:"land_cells"`
	BBox           string  `json:"bbox"` // min_lng,min_lat,max_lng,max_lat, 6 decimals
	ClaimedCells   int     `json:"claimed_cells,omitempty"`
	LastSurveyedAt *string `json:"last_surveyed_at,omitempty"` // UTC, to the second
	BoundarySHA256 string  `json:"boundary_sha256"`
}

type snapPlotNumber struct {
	Province string   `json:"province"` // region slug
	Count    int      `json:"count"`
	SHA256   string   `json:"sha256"` // over "cell:number\n", ordered by number
	First    []string `json:"first"`  // the first 5 "cell:number" pairs
}

type snapPlace struct {
	OSMType   string  `json:"osm_type"`
	OSMID     int64   `json:"osm_id"`
	Kind      string  `json:"kind"`
	NameEn    string  `json:"name_en"`
	NameLocal *string `json:"name_local"`
	Lat       string  `json:"lat"` // 7 decimals, as in OSM
	Lng       string  `json:"lng"`
	Region    *string `json:"region"` // slug
}

type snapPlot struct {
	Cell           string  `json:"cell"`
	PlaceName      *string `json:"place_name"`
	PlaceNameLocal *string `json:"place_name_local"`
	Region         *string `json:"region"`
	District       *string `json:"district"`
	Number         *int    `json:"number"` // plot_numbers, null where the plot has none
	PhotoCount     int     `json:"photo_count"`
}

func importSnapshot(ctx context.Context, d *db.DB) ([]byte, error) {
	s := snapshot{Counts: map[string]int{}, Regions: []snapRegion{}, PlotNumbers: []snapPlotNumber{}, Places: []snapPlace{}, Plots: []snapPlot{}}
	p := d.Pool

	for _, q := range []struct{ name, sql string }{
		{"regions", "select count(*) from regions"},
		{"regions_province", "select count(*) from regions where kind = 'province'"},
		{"regions_district", "select count(*) from regions where kind = 'district'"},
		{"regions_other", "select count(*) from regions where kind not in ('province', 'district')"},
		{"plot_numbers", "select count(*) from plot_numbers"},
		{"places", "select count(*) from places"},
		{"places_without_region", "select count(*) from places where region_id is null"},
		{"plots", "select count(*) from plots"},
		{"photos", "select count(*) from photos"},
		// Thailand's rows only: every opened country adds its own (0152 Laos, …).
		{"place_naming", "select count(*) from place_naming where country = 'th'"},
		{"place_overrides", "select count(*) from place_overrides where country = 'th'"},
	} {
		var n int
		if err := p.QueryRow(ctx, q.sql).Scan(&n); err != nil {
			return nil, fmt.Errorf("%s: %w", q.name, err)
		}
		s.Counts[q.name] = n
	}

	// kind_name arrives with migration 0151; read it only when it exists.
	var hasKindName bool
	if err := p.QueryRow(ctx, `select exists (select 1 from information_schema.columns
		where table_schema = current_schema() and table_name = 'regions' and column_name = 'kind_name')`).Scan(&hasKindName); err != nil {
		return nil, err
	}
	kindName := "null::text"
	if hasKindName {
		kindName = "r.kind_name"
	}
	rows, err := p.Query(ctx, `select r.osm_id, r.kind, `+kindName+`, r.admin_level, r.country, r.slug, r.name_en, r.name_local,
		pr.osm_id, r.urban, r.land_cells,
		to_char(r.min_lng, 'FM990.000000') || ',' || to_char(r.min_lat, 'FM990.000000') || ',' ||
		to_char(r.max_lng, 'FM990.000000') || ',' || to_char(r.max_lat, 'FM990.000000'),
		r.boundary, r.claimed_cells, to_char(r.last_surveyed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
		from regions r left join regions pr on pr.id = r.parent_id
		order by r.osm_id`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var r snapRegion
		var boundary string
		if err := rows.Scan(&r.OSMID, &r.Kind, &r.KindName, &r.AdminLevel, &r.Country, &r.Slug, &r.NameEn, &r.NameLocal,
			&r.ParentOSMID, &r.Urban, &r.LandCells, &r.BBox, &boundary, &r.ClaimedCells, &r.LastSurveyedAt); err != nil {
			rows.Close()
			return nil, err
		}
		sum := sha256.Sum256([]byte(boundary))
		r.BoundarySHA256 = hex.EncodeToString(sum[:])
		s.Regions = append(s.Regions, r)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	rows, err = p.Query(ctx, `select r.slug, pn.cell, pn.number
		from plot_numbers pn join regions r on r.id = pn.region_id
		order by r.slug, pn.number`)
	if err != nil {
		return nil, err
	}
	var cur *snapPlotNumber
	h := sha256.New()
	flush := func() {
		if cur != nil {
			cur.SHA256 = hex.EncodeToString(h.Sum(nil))
			s.PlotNumbers = append(s.PlotNumbers, *cur)
		}
	}
	for rows.Next() {
		var slug, cell string
		var number int
		if err := rows.Scan(&slug, &cell, &number); err != nil {
			rows.Close()
			return nil, err
		}
		if cur == nil || cur.Province != slug {
			flush()
			cur = &snapPlotNumber{Province: slug, First: []string{}}
			h.Reset()
		}
		pair := fmt.Sprintf("%s:%d", cell, number)
		fmt.Fprintln(h, pair)
		cur.Count++
		if len(cur.First) < 5 {
			cur.First = append(cur.First, pair)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	flush()

	rows, err = p.Query(ctx, `select pl.osm_type, pl.osm_id, pl.kind, pl.name_en, pl.name_local,
		to_char(pl.lat, 'FM990.0000000'), to_char(pl.lng, 'FM990.0000000'), r.slug
		from places pl left join regions r on r.id = pl.region_id
		order by pl.osm_type, pl.osm_id`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var x snapPlace
		if err := rows.Scan(&x.OSMType, &x.OSMID, &x.Kind, &x.NameEn, &x.NameLocal, &x.Lat, &x.Lng, &x.Region); err != nil {
			rows.Close()
			return nil, err
		}
		s.Places = append(s.Places, x)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	rows, err = p.Query(ctx, `select p.cell, p.place_name, p.place_name_local, r.slug, dr.slug, pn.number, p.photo_count
		from plots p left join regions r on r.id = p.region_id left join regions dr on dr.id = p.district_id
		left join plot_numbers pn on pn.cell = p.cell
		order by p.cell`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var x snapPlot
		if err := rows.Scan(&x.Cell, &x.PlaceName, &x.PlaceNameLocal, &x.Region, &x.District, &x.Number, &x.PhotoCount); err != nil {
			rows.Close()
			return nil, err
		}
		s.Plots = append(s.Plots, x)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	b, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}
